using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;using OFOQ.Market.Domain.Commerce.Reviews;using OFOQ.Market.Domain.Tenancy;
namespace OFOQ.Market.Infrastructure.Persistence.Configurations.Commerce;
public sealed class TenantTrustMetricSettingsConfiguration:IEntityTypeConfiguration<TenantTrustMetricSettings>
{
 public void Configure(EntityTypeBuilder<TenantTrustMetricSettings> b){b.ToTable("commerce_trust_metric_settings");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasColumnName("id").HasConversion(x=>x.Value,x=>TenantTrustMetricSettingsId.From(x)).ValueGeneratedNever();b.Property(x=>x.TenantId).HasColumnName("tenant_id").HasConversion(x=>x.Value,x=>TenantId.From(x)).IsRequired();b.Property(x=>x.ShowCustomerCount).HasColumnName("show_customer_count").IsRequired();b.Property(x=>x.ShowCompletedOrderCount).HasColumnName("show_completed_order_count").IsRequired();b.Property(x=>x.ShowAverageRating).HasColumnName("show_average_rating").IsRequired();b.Property(x=>x.CreatedAtUtc).HasColumnName("created_at_utc").IsRequired();b.Property(x=>x.CreatedByUserId).HasColumnName("created_by_user_id");b.Property(x=>x.UpdatedAtUtc).HasColumnName("updated_at_utc");b.Property(x=>x.UpdatedByUserId).HasColumnName("updated_by_user_id");b.HasIndex(x=>x.TenantId).IsUnique().HasDatabaseName("ux_trust_metric_settings_tenant");b.HasOne<Tenant>().WithMany().HasForeignKey(x=>x.TenantId).OnDelete(DeleteBehavior.Cascade);}
}
